import {build} from 'esbuild';
import {Miniflare,convertV4MiniflareOptions} from 'miniflare';
export async function createGuestRuntime(enabled=true){
 const bundle=await build({entryPoints:['test/fixtures/hearthsideGuestWorker.mjs'],bundle:true,write:false,platform:'browser',external:['cloudflare:*','node:*'],format:'esm',target:'es2022'});
 const key='34'.repeat(32),keyId='synthetic-guest-key';
 const mf=new Miniflare(convertV4MiniflareOptions({workers:[{name:'app',modules:true,script:bundle.outputFiles[0]!.text,compatibilityDate:'2026-08-27',compatibilityFlags:['nodejs_compat'],durableObjects:{HEARTHSIDE_GUEST_ROOMS:{className:'TestRoom',useSQLite:true},RECOVERY_ROOMS:{className:'TestRoom',useSQLite:true},HEARTHSIDE_GUEST_CARDS:{className:'HearthsideGuestCard',useSQLite:true},HEARTHSIDE_GUEST_INDEXES:{className:'HearthsideGuestIndex',useSQLite:true},LEDGER_ROOMS:{className:'TestSource',useSQLite:true},CONTROL:{className:'TestControl',useSQLite:true}},r2Buckets:['HEARTHSIDE_GUEST_ARCHIVE','HEARTHSIDE_GUEST_MEDIA'],serviceBindings:{HEARTHSIDE_GUEST_CONTROL_PLANE:'control'},bindings:{HEARTHSIDE_GUESTS_ENABLED:String(enabled),HEARTHSIDE_GUEST_PUBLICATION:'true',SUPABASE_URL:'https://synthetic.test',SUPABASE_PUBLISHABLE_KEY:'synthetic',HEARTHSIDE_GUEST_AUTHORITY_KEY:key,HEARTHSIDE_GUEST_AUTHORITY_KEY_ID:keyId}},{name:'control',modules:true,script:`export default {async fetch(request,env){try {const token=request.headers.get('Authorization').slice(7);return Response.json(await env.CONTROL.get(env.CONTROL.idFromName('control')).authority(token,await request.json()));}catch{return new Response('',{status:403});}}};`,compatibilityDate:'2026-08-27',durableObjects:{CONTROL:{className:'TestControl',scriptName:'app',useSQLite:true}}}]}));
 const request=(path:string,actor='alice',body?:unknown)=>mf.dispatchFetch('http://localhost/api/hearthside-guests/development/'+path,{method:body?'POST':'GET',headers:{Authorization:`Bearer ${actor}.synthetic.jwt`,'Content-Type':'application/json'},...(body?{body:JSON.stringify(body)}:{})});
 const control=(body:unknown)=>mf.dispatchFetch('http://localhost/__test/control',{method:'POST',body:JSON.stringify(body)});
 return {mf,request,control};
}
